        return False
    delta = Fraction(D, NM)
    if Fraction(dn, dd) != delta:
        return False
    if D > 0:
        if delta < Fraction(1, NM):
            return False
        if lip and (D % 2 != 0 or delta < Fraction(2, NM)):
            return False
    kn = case.get("kappa_num")
    kd = case.get("kappa_den")
    if not is_int(kn) or not is_int(kd) or kd < 1:
        return False
    if D == 0:
