def mm(A, B):
    return [[A[0][0]*B[0][0] + A[0][1]*B[1][0], A[0][0]*B[0][1] + A[0][1]*B[1][1]],
            [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]]

def det2(A):
    return A[0][0]*A[1][1] - A[0][1]*A[1][0]

def tr2(A):
    return A[0][0] + A[1][1]

def trans(A):
    return [[A[0][0], A[1][0]], [A[0][1], A[1][1]]]

def gl_inv(A):
    d = det2(A)
    if d*d != 1:
        return None
    return [[d*A[1][1], -d*A[0][1]], [-d*A[1][0], d*A[0][0]]]

def qmat(a):
    return [[a, 1], [1, 0]]

def cf_list(num, den):
    out = []
    while den != 0:
        a = num // den
        out.append(a)
        num, den = den, num - a*den
    return out

def pingala_word(qs):
    W = [[1, 0], [0, 1]]
    for a in qs:
        W = mm(qmat(a), W)
    return W

def convergents(qs):
    out = []
    hm2, hm1 = 0, 1
    km2, km1 = 1, 0
    for a in qs:
        h = a*hm1 + hm2
        k = a*km1 + km2
        out.append((h, k))
        hm2, hm1 = hm1, h
        km2, km1 = km1, k
    return out

def commutator(W, V):
    return mm(mm(W, V), mm(gl_inv(W), gl_inv(V)))

def defect_gl2(W, V):
    x = tr2(W)
    y = tr2(V)
    z = tr2(mm(W, V))
    d = det2(W)
    e = det2(V)
    return Fraction(e*x*x + d*y*y + z*z - x*y*z - 2*d*e, d*e), x, y, z, d, e

def defect_sector(t, z, s):
    return z*z - t*t*z + 2*s*t*t - 2

def fib_pair(n):
    M = [[1, 1], [1, 0]]
    R = [[1, 0], [0, 1]]
    e = n
    while e > 0:
        if e % 2 == 1:
            R = mm(R, M)
        M = mm(M, M)
        e = e // 2
    return R[0][1]

