from itertools import combinations

def pairwise_consistent(moduli, residues):
    for i, j in combinations(range(len(moduli)), 2):
        g = gcd(moduli[i], moduli[j])
        if (residues[i] - residues[j]) % g != 0:
            return False
    return True

def net_lcm(moduli):
    L = 1
    for m in moduli:
        L = L // gcd(L, m) * m
    return L

def check_case(case):
    moduli = [int(x) for x in case["moduli"]]
    residues = [int(x) for x in case["residues"]]
    expected = bool(case["expected_solvable"])
    pred = pairwise_consistent(moduli, residues)
    if pred != expected:
        return False
    if not pred:
        return True
    L = net_lcm(moduli)
    prod = 1
    for m in moduli:
        prod *= m
    if prod % L != 0:
        return False
    comp = prod // L
    if "lcm" in case and int(case["lcm"]) != L:
        return False
    if "compression" in case and int(case["compression"]) != comp:
        return False
    if comp < 1:
        return False
    coprime = True
    for i, j in combinations(range(len(moduli)), 2):
        if gcd(moduli[i], moduli[j]) != 1:
            coprime = False
    if comp <= 1 and not coprime:
        return False
    return True

