def _inv_m1(A):
    return (-A[3], A[1], A[2], -A[0])

def _is_square_q(num, den):
    if num < 0 or den <= 0:
        return False
    g = gcd(abs(num), den)
    num //= g
    den //= g
    return isqrt(num) * isqrt(num) == num and isqrt(den) * isqrt(den) == den

def _comm_trace(a, b):
    A = (a, 1, 1, 0)
    B = (b, 1, 1, 0)
    if _det(A) != -1 or _det(B) != -1:
        return 2
    C = _mul(_mul(_mul(A, B), _inv_m1(A)), _inv_m1(B))
    if _det(C) != 1:
        return 2
    return C[0] + C[3]

