    if Fraction(dan, dad) != Fraction(688, 15625):
        return False
    ratio = Fraction(dan, dad) / Fraction(dbn, dbd)
    if ratio != Fraction(344, 425):
        return False
    if _is_square_q(ratio.numerator, ratio.denominator):
        return False
    bch = case["bch"]
