def rot(p):
    w, x, y, z = p
    n = w * w + x * x + y * y + z * z
    m = [[w*w + x*x - y*y - z*z, 2*(x*y - w*z), 2*(x*z + w*y)],
         [2*(x*y + w*z), w*w - x*x + y*y - z*z, 2*(y*z - w*x)],
         [2*(x*z - w*y), 2*(y*z + w*x), w*w - x*x - y*y + z*z]]
    return [[Fraction(m[i][j], n) for j in range(3)] for i in range(3)]


