    return -1


def quat_side(case):
    A = tuple(int(c) for c in case["A"])
    B = tuple(int(c) for c in case["B"])
    if len(A) != 4 or len(B) != 4:
        return None
    pa, pb = parity_class(A), parity_class(B)
    if pa < 0 or pb < 0:
        return None
    nA = sum(c * c for c in A)
    nB = sum(c * c for c in B)
    if nA == 0 or nB == 0 or nA % 4 != 0 or nB % 4 != 0:
        return None
    a, b = nA // 4, nB // 4
    ab = a * b
    W = cross3(A[1:], B[1:])
    w2 = sum(c * c for c in W)
    if w2 % 8 != 0:
        return None
    D = w2 // 8
    dot = A[0] * B[0] - (A[1] * B[1] + A[2] * B[2] + A[3] * B[3])
    if dot % 2 != 0:
        return None
    x, y, z = A[0], B[0], dot // 2
    kap = fricke_kappa(a, b, x, y, z)
    if kap != 2 * D or 4 * kap != w2:
        return None
    PQ = qmul(A, B)
    QP = qmul(B, A)
    comm_add = tuple(PQ[i] - QP[i] for i in range(4))
    if comm_add[0] != 0 or sum(c * c for c in comm_add) != 16 * kap:
        return None
    T = qmul(qmul(PQ, qconj(A)), qconj(B))
    if T[0] % 16 != 0:
        return None
    reC = T[0] // 16
    if reC != ab - D or sum(c * c for c in T) != 256 * ab * ab:
        return None
    if Fraction(2 * reC, ab) != 2 - Fraction(kap, ab):
        return None
    if pa == 0 and pb == 0 and D % 2 != 0:
        return None
    if kap < 0:
        return None
    RA, RB = rot(A), rot(B)
    X = mm(RA, RB)
    Y = mm(RB, RA)
    F = sum((X[i][j] - Y[i][j]) ** 2 for i in range(3) for j in range(3))
    delta = Fraction(D, ab)
    if F != 16 * delta * (1 - delta / 2):
        return None
    Ft = F * ab * ab
    if Ft.denominator != 1:
        return None
    Ft = Ft.numerator
    if Ft != 8 * D * (2 * ab - D) or Ft != 2 * kap * (4 * ab - kap):
        return None
    if Ft % 16 != 8 * (D % 2):
        return None
    if (Ft == 0) != (D == 0 or D == 2 * ab):
        return None
    if 0 < D < 2 * ab:
        floor = 32 * (ab - 1) if (pa == 0 and pb == 0) else 8 * (2 * ab - 1)
        if Ft < floor:
            return None
    cls = "lipschitz" if (pa == 0 and pb == 0) else ("hurwitz_odd" if (pa == 1 and pb == 1) else "mixed")
    return {"D": D, "kappa": kap, "F_cleared": Ft, "reC": reC, "norm_product": ab,
            "class": cls, "D_parity": D % 2, "commuting": D == 0}


