def tr2(m):
    return m[0][0] + m[1][1]


def inv2(m):
    d = det2(m)
    return [[m[1][1] * d, -m[0][1] * d], [-m[1][0] * d, m[0][0] * d]]


def cf(num, den):
    out = []
    while den:
        out.append(num // den)
        num, den = den, num % den
    return out


def split_side(case):
    num, den = int(case["num"]), int(case["den"])
    if not (num > den > 0) or gcd(num, den) != 1:
        return None
    qs = cf(num, den)
    if len(qs) > 1 and qs[-1] < 2:
        return None
    W = [[1, 0], [0, 1]]
    for a in qs:
        W = mat2(W, qmat(a))
    V = [[1, 0], [0, 1]]
    for a in reversed(qs):
        V = mat2(V, qmat(a))
    if W[0][0] != num or W[1][0] != den:
        return None
    if V != [[W[0][0], W[1][0]], [W[0][1], W[1][1]]]:
        return None
    s = det2(W)
    if s != (-1) ** len(qs) or det2(V) != s:
        return None
    x, y, z = tr2(W), tr2(V), tr2(mat2(W, V))
    kap = fricke_kappa(s, s, x, y, z)
    WV, VW = mat2(W, V), mat2(V, W)
    K = [[WV[i][j] - VW[i][j] for j in range(2)] for i in range(2)]
    if K[0][1] != K[1][0] or K[0][0] != -K[1][1]:
        return None
    if det2(K) != kap or kap != -(K[0][0] ** 2 + K[0][1] ** 2):
        return None
    p, q, r, t = W[0][0], W[0][1], W[1][0], W[1][1]
    if kap != -((p - t) ** 2 + (q + r) ** 2) * (q - r) ** 2:
        return None
    C = mat2(mat2(WV, inv2(W)), inv2(V))
    if det2(C) != 1:
        return None
    trC = tr2(C)
    if trC != 2 - kap * s * s:
        return None
    for g in ([[1, 1], [0, 1]], [[0, 1], [1, 0]], [[2, 1], [1, 1]]):
        if tr2(mat2(mat2(g, C), inv2(g))) != trC:
            return None
    naive = x * x + y * y + z * z - x * y * z - 2
    if naive - trC != 2 * (1 - s) * x * x:
        return None
    if kap > 0:
        return None
    if (kap == 0) != (qs == qs[::-1]):
        return None
    return {"trace": trC, "kappa": kap, "sector": s, "naive_sl2": naive,
            "commuting": kap == 0, "t": x, "z": z}


def check_case(case):
    try:
        expect = case.get("expected")
        if not (expect is True or expect is False):
            return False
        side = case.get("side")
        if side == "definite":
            got = quat_side(case)
        elif side == "split":
            got = split_side(case)
        else:
            return False
        if got is None:
            return False
        claims = case.get("claims")
        if not claims:
            return False
        pred = True
        for key in claims:
            if key not in got or got[key] != claims[key]:
                pred = False
        return pred == expect
    except Exception:
        return False

from fractions import Fraction
from math import gcd

def qnorm2(p):
    return p[0]*p[0] + p[1]*p[1] + p[2]*p[2] + p[3]*p[3]

def qmul(p, q):
    a0, a1, a2, a3 = p
    b0, b1, b2, b3 = q
    return (a0*b0 - a1*b1 - a2*b2 - a3*b3,
            a0*b1 + a1*b0 + a2*b3 - a3*b2,
            a0*b2 - a1*b3 + a2*b0 + a3*b1,
            a0*b3 + a1*b2 - a2*b1 + a3*b0)

def qconj(p):
    return (p[0], -p[1], -p[2], -p[3])

def cross(u, v):
    return (u[1]*v[2] - u[2]*v[1],
            u[2]*v[0] - u[0]*v[2],
            u[0]*v[1] - u[1]*v[0])

def same_parity(a):
    r = a[0] % 2
    return all(c % 2 == r for c in a)

def pairwise_ok(moduli, residues):
    n = len(moduli)
    for i in range(n):
        for j in range(i + 1, n):
            if (residues[i] - residues[j]) % gcd(moduli[i], moduli[j]) != 0:
                return False
    return True

def pairwise_coprime(moduli):
    n = len(moduli)
    for i in range(n):
        for j in range(i + 1, n):
            if gcd(moduli[i], moduli[j]) != 1:
                return False
    return True

def crt_pair(r1, m1, r2, m2):
    g = gcd(m1, m2)
    if (r2 - r1) % g != 0:
        return None
    l = m1 // g * m2
    m2g = m2 // g
    if m2g == 1:
        t = 0
    else:
        t = ((r2 - r1) // g * pow(m1 // g, -1, m2g)) % m2g
    return ((r1 + m1 * t) % l, l)

def crt_net(moduli, residues):
    if not moduli or len(moduli) != len(residues):
        return None
    r = residues[0] % moduli[0]
    m = moduli[0]
    prod = moduli[0]
    for k in range(1, len(moduli)):
        mi = moduli[k]
        prod *= mi
        out = crt_pair(r, m, residues[k] % mi, mi)
        if out is None:
            return None
        r, m = out
    return (r, m, prod)

def predict(case):
    A = tuple(case['A'])
    B = tuple(case['B'])
    if len(A) != 4 or len(B) != 4:
        return False
    if not same_parity(A) or not same_parity(B):
        return False
    na = qnorm2(A)
    nb = qnorm2(B)
    if na == 0 or nb == 0 or na % 4 != 0 or nb % 4 != 0:
        return False
    N = na // 4
    M = nb // 4
    NM = N * M
    W = cross(A[1:], B[1:])
    w2 = W[0]*W[0] + W[1]*W[1] + W[2]*W[2]
    if w2 % 8 != 0:
        return False
    D = w2 // 8
    reC = NM - D
    T = qmul(qmul(qmul(A, B), qconj(A)), qconj(B))
    if T[0] != 16 * reC:
        return False
    if qnorm2(T) != 256 * NM * NM:
        return False
    lips = all(c % 2 == 0 for c in A) and all(c % 2 == 0 for c in B)
    if lips and D % 2 != 0:
        return False
    if case['claimed_D'] != D:
        return False
    sector = 'lipschitz' if lips else 'hurwitz'
    if case['claimed_sector'] != sector:
        return False
    cd = case['claimed_delta']
    ck = case['claimed_kappa']
    if len(cd) != 2 or len(ck) != 2 or cd[1] <= 0 or ck[1] <= 0:
        return False
    delta = Fraction(D, NM)
    kappa = Fraction(NM + abs(reC), D) if D > 0 else Fraction(0, 1)
    if Fraction(cd[0], cd[1]) != delta:
        return False
    if Fraction(ck[0], ck[1]) != kappa:
        return False
    if D > 0:
        if delta < Fraction(1, NM):
            return False
        if lips and delta < Fraction(2, NM):
            return False
        if kappa < 1:
            return False
        if kappa * delta != 1 + Fraction(abs(reC), NM):
            return False
    else:
        if reC != NM or T[0] <= 0:
            return False
    moduli = case['moduli']
    residues = case['residues']
    if not moduli or any(m <= 0 for m in moduli):
        return False
    if not pairwise_ok(moduli, residues):
        return False
    net = crt_net(moduli, residues)
    if net is None:
        return False
    r, L, prod = net
    if prod % L != 0:
        return False
    comp = prod // L
    if comp != case['claimed_compression']:
        return False
    if (comp == 1) != pairwise_coprime(moduli):
        return False
    if r != D % L:
        return False
    return True

def check_case(case):
    if not isinstance(case.get('expect_ok'), bool):
        return False
    return bool(predict(case) == case['expect_ok'])

from fractions import Fraction
from math import gcd
from itertools import combinations

ID = [[1, 0], [0, 1]]


def mm(A, B):
    return [[A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]


def dt(A):
    return A[0][0] * A[1][1] - A[0][1] * A[1][0]


def tr(A):
    return A[0][0] + A[1][1]


def adj(A):
    return [[A[1][1], -A[0][1]], [-A[1][0], A[0][0]]]


def invm(A):
    d = dt(A)
    if d == 1:
        return adj(A)
    if d == -1:
        B = adj(A)
        return [[-B[0][0], -B[0][1]], [-B[1][0], -B[1][1]]]
    return None


def word(cf, rev):
    W = ID
    seq = list(cf)
    if rev:
        seq.reverse()
    for a in seq:
        W = mm(W, [[a, 1], [1, 0]])
    return W


def conv(cf):
    ps = []
    qs = []
    pm2, pm1, qm2, qm1 = 0, 1, 1, 0
    for a in cf:
        ps.append(a * pm1 + pm2)
        qs.append(a * qm1 + qm2)
        pm2, pm1 = pm1, ps[-1]
        qm2, qm1 = qm1, qs[-1]
    return ps, qs


def fibd(n):
    if n == 0:
        return (0, 1)
    a, b = fibd(n >> 1)
    c = a * ((b << 1) - a)
    d = a * a + b * b
    if n % 2 == 1:
        return (d, c + d)
    return (c, d)


def fibl(n):
    a, b = 0, 1
    k = n
    while k > 0:
        a, b = b, a + b
        k -= 1
    return a


def nsub(lam):
    tot = 0
    for k in range(0, lam + 1):
        for pos in combinations(range(lam), k):
            good = True
            for i in range(1, len(pos)):
                if pos[i] - pos[i - 1] < 2:
                    good = False
            if good:
                tot += 1
    return tot


def ping_guard(cf):
    lam = len(cf) + 4
    if lam > 16:
        return False
    fb, fb1 = fibd(lam)
    if fb != fibl(lam) or fb1 != fibl(lam + 1):
        return False
    if nsub(lam) != fibl(lam + 2):
        return False
    ones = True
    for a in cf:
        if a != 1:
            ones = False
    if ones:
        ps, qs = conv(cf)
        for i in range(len(cf)):
            if qs[i] != fibl(i + 1) or ps[i] != fibl(i + 2):
                return False
    return True


def fdet(M):
    return M[0][0] * M[1][1] - M[0][1] * M[1][0]


def finv(M):
    d = fdet(M)
    if d == 0:
        return None
    return [[M[1][1] / d, -M[0][1] / d], [-M[1][0] / d, M[0][0] / d]]


def cayley(W):
    S = [[Fraction(1 - W[0][0]), Fraction(-W[0][1])], [Fraction(-W[1][0]), Fraction(1 - W[1][1])]]
    T = [[Fraction(1 + W[0][0]), Fraction(W[0][1])], [Fraction(W[1][0]), Fraction(1 + W[1][1])]]
    Ti = finv(T)
    if Ti is None:
        return None
    return mm(S, Ti)


def gmul(z, w):
    return (z[0] * w[0] - z[1] * w[1], z[0] * w[1] + z[1] * w[0])


def gsub(z, w):
    return (z[0] - w[0], z[1] - w[1])


def su2_det(p, q, r):
    a = Fraction(q)
    b = Fraction(p)
    c = Fraction(r) * Fraction(q)
    d = Fraction(0)
    return gsub(gmul((a, b), (a, -b)), gmul((c, d), (-c, d)))


def su2_norm(p, q, r):
    return Fraction(q) * Fraction(q) + Fraction(p) * Fraction(p) + (Fraction(r) * Fraction(q)) * (Fraction(r) * Fraction(q))


def data(cf, rn, rd):
    L = len(cf)
    if L < 1 or cf[0] < 1 or rd < 1:
        return None
    for i in range(1, L):
        if cf[i] < 1:
            return None
    if gcd(abs(rn), rd) != 1:
        return None
    W = word(cf, False)
    V = word(cf, True)
    ps, qs = conv(cf)
    iW = invm(W)
    iV = invm(V)
    if iW is None or iV is None:
        return None
    C = mm(mm(mm(W, V), iW), iV)
    x = tr(W)
    y = tr(V)
    z = tr(mm(W, V))
    a = dt(W)
    b = dt(V)
    if a * b == 0:
        return None
    tw = Fraction(b * x * x + a * y * y + z * z - x * y * z, a * b) - 2
    sec = z * z - x * x * z + 2 * a * x * x - 2
    unn = x * x + y * y + z * z - x * y * z - 2
    return {'cf': list(cf), 'L': L, 'W': W, 'V': V, 'ps': ps, 'qs': qs, 'sh': a,
            'C': C, 't': x, 'z': z, 'tw': tw, 'sec': sec, 'unn': unn,
            'trC': tr(C), 'detC': dt(C), 'rn': rn, 'rd': rd}


def ok_struct(d):
    L = d['L']
    W = d['W']
    ps = d['ps']
    qs = d['qs']
    if d['sh'] != (-1) ** L:
        return False
    pp = ps[L - 2] if L >= 2 else 1
    pq = qs[L - 2] if L >= 2 else 0
    if W != [[ps[L - 1], pp], [qs[L - 1], pq]]:
        return False
    if d['V'] != [[W[0][0], W[1][0]], [W[0][1], W[1][1]]]:
        return False
    if d['detC'] != 1 or d['sh'] * d['sh'] != 1:
        return False
    if d['t'] != tr(W) or d['t'] != tr(d['V']):
        return False
    if d['z'] != W[0][0] ** 2 + W[0][1] ** 2 + W[1][0] ** 2 + W[1][1] ** 2:
        return False
    if d['tw'].denominator != 1 or d['tw'] != d['trC'] or d['sec'] != d['trC']:
        return False
    p1 = d['z'] ** 2 - d['t'] ** 2 * d['z'] + 2 * d['t'] ** 2 - 2
    m1 = d['z'] ** 2 - d['t'] ** 2 * d['z'] - 2 * d['t'] ** 2 - 2
    if p1 - m1 != 4 * d['t'] ** 2:
        return False
    if p1 != d['z'] ** 2 - d['t'] ** 2 * d['z'] + 2 * d['t'] ** 2 - 2:
        return False
    cy = cayley(W)
    if cy is None or fdet(cy) != d['sh']:
        return False
    if not ping_guard(d['cf']):
        return False
    return True


def quat(d):
    L = d['L']
    if L < 2:
        return None
    ps = d['ps']
    qs = d['qs']
    r = Fraction(d['rn'], d['rd'])
    px = ps[L - 1]
    qx = qs[L - 1]
    py = ps[L - 2]
    qy = qs[L - 2]
    farey = px * qy - py * qx
    nx = Fraction(qx) ** 2 + Fraction(px) ** 2 + r * r * Fraction(qx) ** 2
    ny = Fraction(qy) ** 2 + Fraction(py) ** 2 + r * r * Fraction(qy) ** 2
    cross = r * r * Fraction(farey) ** 2 / (nx * ny)
    xr = Fraction(px, qx)
    yr = Fraction(py, qy)
    hh = (1 + xr * xr + r * r) * (1 + yr * yr + r * r)
    dl = 2 * r * r / (Fraction(qx * qy) ** 2 * hh)
    cert = True
    if su2_det(px, qx, r) != (su2_norm(px, qx, r), Fraction(0)):
        cert = False
    if su2_det(py, qy, r) != (su2_norm(py, qy, r), Fraction(0)):
        cert = False
    return {'farey': farey, 'cross': cross, 'delta': 2 * cross, 'delta_f': dl, 'cert': cert}


def predict(claim, d):
    if d is None:
        return False
    if not ok_struct(d):
        return False
    if claim == 'twist_required':
        return d['tw'] == d['trC'] and d['unn'] != d['trC']
    if claim == 'untwisted_sl2':
        return d['unn'] == d['trC']
    if claim == 'commutes':
        return d['trC'] == 2
    if claim == 'degenerate':
        return d['L'] == 1 and d['trC'] == 2 and d['unn'] != d['trC'] and d['sh'] == -1
    if claim == 'quat_bridge':
        qd = quat(d)
        if qd is None:
            return False
        return (qd['farey'] * qd['farey'] == 1 and qd['cross'] == qd['delta_f'] / 2
                and qd['delta_f'] > 0 and qd['delta'] == 2 * qd['cross'] and qd['cert'])
    if claim == 'palindrome_split':
        W = d['W']
        qd = quat(d)
        if qd is None:
            return False
        return (W[0][1] == W[1][0] and d['C'] == ID and d['trC'] == 2 and d['sec'] == 2
                and qd['cross'] == qd['delta_f'] / 2 and qd['delta_f'] > 0)
    return False


def check_case(case):
    if not isinstance(case, dict):
        return False
    claim = case.get('claim')
    cf = case.get('cf')
    off = case.get('offset')
    exp = case.get('expected')
    if claim is None or cf is None or off is None or exp is None:
        return False
    if len(off) != 2:
        return False
    d = data(cf, off[0], off[1])
    pred = predict(claim, d)
    return bool(pred) is bool(exp)

from fractions import Fraction
from math import gcd
from itertools import combinations

def cross3(u, v):
    return (u[1]*v[2] - u[2]*v[1],
            u[2]*v[0] - u[0]*v[2],
            u[0]*v[1] - u[1]*v[0])

def qnorm4(a):
    return a[0]*a[0] + a[1]*a[1] + a[2]*a[2] + a[3]*a[3]

def qmul(a, b):
    w1, x1, y1, z1 = a
    w2, x2, y2, z2 = b
    return (w1*w2 - x1*x2 - y1*y2 - z1*z2,
            w1*x2 + x1*w2 + y1*z2 - z1*y2,
            w1*y2 - x1*z2 + y1*w2 + z1*x2,
            w1*z2 + x1*y2 - y1*x2 + z1*w2)

def qconj(a):
    return (a[0], -a[1], -a[2], -a[3])

def same_parity(a):
    return a[0] % 2 == a[1] % 2 and a[1] % 2 == a[2] % 2 and a[2] % 2 == a[3] % 2

def is_all_even(a):
    return all(x % 2 == 0 for x in a)

def hurwitz_D(A, B):
    W = cross3((A[1], A[2], A[3]), (B[1], B[2], B[3]))
    s = W[0]*W[0] + W[1]*W[1] + W[2]*W[2]
    if s % 8 != 0:
        return None
    return s // 8

def parity_pred(A, B):
    if not (same_parity(A) and same_parity(B)):
        return False
    if qnorm4(A) % 4 != 0 or qnorm4(B) % 4 != 0:
        return False
    n2 = qnorm4(A) // 4
    m2 = qnorm4(B) // 4
    if n2 <= 0 or m2 <= 0:
        return False
    D = hurwitz_D(A, B)
    if D is None or D < 0:
        return False
    lip = is_all_even(A) and is_all_even(B)
    if lip and D % 2 != 0:
        return False
    delta = Fraction(D, n2*m2)
    bound = Fraction(2 if lip else 1, n2*m2)
    if D > 0 and delta < bound:
        return False
    T = qmul(qmul(qmul(A, B), qconj(A)), qconj(B))
    if T[0] != 16*(n2*m2 - D):
        return False
    if qnorm4(T) != 256*n2*m2*n2*m2:
        return False
    return True

def lcm2(a, b):
    return a // gcd(a, b) * b

def crt_pred(moduli, residues):
    n = len(moduli)
    if n == 0 or len(residues) != n:
        return False
    if any(m <= 0 for m in moduli):
        return False
    pairwise_coprime = True
    for i, j in combinations(range(n), 2):
        g = gcd(moduli[i], moduli[j])
        if g != 1:
            pairwise_coprime = False
        if (residues[i] - residues[j]) % g != 0:
            return False
    L = 1
    P = 1
    for m in moduli:
        L = lcm2(L, m)
        P = P * m
    if P % L != 0:
        return False
    comp = P // L
    if (comp == 1) != pairwise_coprime:
        return False
    return True

def farey_pred(p, q, r, t, sn, sd):
    if q <= 0 or t <= 0 or sd == 0:
        return False
    if abs(p*t - r*q) != 1:
        return False
    if gcd(q, t) != 1:
        return False
    gap = Fraction(abs(p*t - r*q), q*t)
    if gap != Fraction(1, q*t):
        return False
    if lcm2(q, t) != q*t:
        return False
    defect = Fraction(2*sn*sn, sd*sd*q*q*t*t)
    if sn != 0 and defect <= 0:
        return False
    return True

def check_case(case):
    kind = case["kind"]
    expected = case["expected"]
    if kind == "parity":
        pred = parity_pred(case["A"], case["B"])
    elif kind == "crt":
        pred = crt_pred(case["moduli"], case["residues"])
    elif kind == "farey":
        pred = farey_pred(case["p"], case["q"], case["r"], case["t"], case["sn"], case["sd"])
    else:
        pred = False
    return pred == expected

