def mul(A,B):
    return ((A[0][0]*B[0][0]+A[0][1]*B[1][0], A[0][0]*B[0][1]+A[0][1]*B[1][1]),(A[1][0]*B[0][0]+A[1][1]*B[1][0], A[1][0]*B[0][1]+A[1][1]*B[1][1]))
def dt(A):
    return A[0][0]*A[1][1]-A[0][1]*A[1][0]
def tr(A):
    return A[0][0]+A[1][1]
def adj(A):
    return ((A[1][1],-A[0][1]),(-A[1][0],A[0][0]))
def word(cf):
    W=((1,0),(0,1))
    for a in cf:
        W=mul(W,((a,1),(1,0)))
    return W
def comm(A,B):
    d,e=dt(A),dt(B)
    N=mul(mul(mul(A,B),adj(A)),adj(B))
    de=d*e
    return tr(N)//de, dt(N)//(de*de)
